import { Component } from '@angular/core';
import { HeaderComponent } from './header/header.component';
import { PagosPendientesComponent } from './pagos-pendientes/pagos-pendientes.component';
import { ProximoPagoComponent } from './proximo-pago/proximo-pago.component';
import { UltimosAbonosComponent } from './ultimos-abonos/ultimos-abonos.component';
import { UtilsEstadoCuentaService } from '../../../main/estado-cuenta/services/utils-estado-cuenta.service';
import { CreditoService } from '../../../controllers/credito.service';
import { Credito } from '../../../models/credito.model';
import { LocalStorageService } from '../../../services/localStorage/local-storage.service';
import { ComprobacionesComponent } from './comprobaciones/comprobaciones.component';

@Component({
    selector: 'app-dashboard-clientes',
    imports: [
        HeaderComponent,
        PagosPendientesComponent,
        ProximoPagoComponent,
        UltimosAbonosComponent
    ],
    templateUrl: './dashboard-clientes.component.html',
    styleUrl: './dashboard-clientes.component.css'
})

export class DashboardClientesComponent {
  creditos?: Credito[]

  ultimoCreditoActivo?: Credito;
  creditosPagos: any[] = [];
  creditoComprobaciones: any[] = [];
  abonos: any[] = [];

  relations=[
    'estadoCuenta',
    'creditosPagos',
    'convenios.conveniosPagos',
    'abonos',
    'productosFinancieros',
    'creditoComprobaciones'
  ]

  constructor(
    private storage: LocalStorageService,
    private creditoController: CreditoService,
    private utilsEstadoCuenta: UtilsEstadoCuentaService,
  ) { }

  ngOnInit(){
    this.getDataFromCreditoActivo()
  }

  public async getDataFromCreditoActivo(){
    const login = this.storage.getClienteUser()

    this.creditos = await this.creditoController.all([
      {
        key: 'cliente_id',
        operator: '=',
        value: login?.id ?? null
      },
      {
        key: 'estado',
        operator: '=',
        value: 'ACTIVO'
      }
    ], this.relations, {})

    const creditosConPagos = this.creditos.filter(credito =>
      Array.isArray(credito.creditos_pagos) && credito.creditos_pagos.length > 0
    );

    if (creditosConPagos.length > 0) {
      const ultimoCredito = creditosConPagos[creditosConPagos.length - 1];
      ultimoCredito.estado_cuenta = this.utilsEstadoCuenta.calculateEstadoDeCuenta(ultimoCredito);

      this.ultimoCreditoActivo = ultimoCredito;
      this.creditosPagos = ultimoCredito.creditos_pagos ?? [];
      this.creditoComprobaciones = ultimoCredito.credito_comprobaciones ?? [];
      this.abonos = ultimoCredito.abonos ?? [];

      console.log("Comprobaciones:", this.creditoComprobaciones);
    } else {
      this.creditos = [];
      console.error('No hay creditos activos con pagos');
    }
  }

}
