import { Component } from '@angular/core';
import { ClienteCreditosComponent } from "../../shared/cliente-creditos/cliente-creditos.component";
import { Credito } from '../../../models/credito.model';

import { estadoCuenta } from '../../../services/documentosLegales/contratos/contrato_estado_de_cuenta.service';
import { ResumenEtadoCuentaClienteComponent } from "./resumen-estado-cuenta/resumen-estado-cuenta.component";
import { CreditoService } from '../../../controllers/credito.service';
import { UtilsEstadoCuentaService } from '../../../main/estado-cuenta/services/utils-estado-cuenta.service';

@Component({
  selector: 'app-cliente-estados-cuentas',
  imports: [
    ClienteCreditosComponent,
    ResumenEtadoCuentaClienteComponent
  ],
  templateUrl: './cliente-estados-cuentas.component.html',
  styleUrl: './cliente-estados-cuentas.component.css'
})
export class ClienteEstadosCuentasComponent {
  credito?: Credito

  constructor(
    public estadoCuentePdf: estadoCuenta,
    private estadoCuentaUtils: UtilsEstadoCuentaService,
    private creditoController: CreditoService,
  ) { }

  async onCreditoSelected(credito: Credito) {
    const res = await this.creditoController.find(credito.id, ['*'], false)
    if (res) {
      this.credito = res
      this.credito.estado_cuenta = this.estadoCuentaUtils.calculateEstadoDeCuenta(credito)
    }
  }
}
