import { Routes } from "@angular/router";
import { DashboardClientesComponent } from "./dashboard-clientes/dashboard-clientes.component";
import { CotizadorComponent } from "../../main/cotizador/cotizador.component";
import { ClientePerfilComponent } from "./cliente-perfil/cliente-perfil.component";
import { ClienteEstadosCuentasComponent } from "./cliente-estados-cuentas/cliente-estados-cuentas.component";
import { ClientesCreditosComponent } from "./creditos/creditos.component";
import { CreditoFormComponent } from "../../main/creditos/credito-form/credito-form.component";
// import { ClientesCreditoFormNuevoComponent } from "./creditos/form-nuevo/form-nuevo.component";
import { ApoyosClientesComponent } from "./apoyos/apoyos-clientes.component";
import { NuevoApoyoComponent } from "./apoyos/nuevo-apoyo/nuevo-apoyo.component";
import { FormApoyosComponent } from "../../main/apoyos/form-apoyos/form-apoyos.component";

export const mainRoutes: Routes = [
  { path: '', pathMatch: 'full', redirectTo: 'dashboard' },
  { path: 'dashboard', component: DashboardClientesComponent },
  { path: 'cotizador', component: CotizadorComponent },
  { path: 'creditos', component: ClientesCreditosComponent },
  { path: 'apoyos', component: ApoyosClientesComponent },
  {
    path: 'editar/:credito_id',
    component: CreditoFormComponent,
    loadChildren: () => import('../../main/creditos/credito-form/credito.form.routes').then(m => m.creditoFormRoutes),
  },
  {
    path: 'nuevo-credito',
    loadComponent: () => import('./creditos/form-nuevo/form-nuevo.component').then(m => m.ClientesCreditoFormNuevoComponent)
  },
  // {
  //   path: 'nuevo-apoyo/:prog_id',
  //   component: NuevoApoyoComponent,
  //   //loadComponent: () => import('./apoyos/nuevo-apoyo/nuevo-apoyo.component').then(m => m.NuevoApoyoComponent)
  // },
  { path: 'estado-cuenta', component: ClienteEstadosCuentasComponent },
  { path: 'estado-cuenta/:credito_id', component: ClienteEstadosCuentasComponent },
  {
    path: 'perfil',
    component: ClientePerfilComponent,
    children: [
      {
        path: '',
        loadChildren: () =>
          import('./cliente-perfil/cliente-perfil.routes').then(m => m.CLIENTE_PERFIL_ROUTES),
      }
    ]
  },
  {
    title: 'Apoyos Formulario',
    path: 'editar-apoyo/:apoyo_id',
    component: FormApoyosComponent,
    loadChildren: () => import('../../main/apoyos/form-apoyos/form.apoyos.routes').then(m => m.formApoyosRoutes)
  }

]
