import { Component, EventEmitter, OnInit, Output } from '@angular/core';
import { CreditoService } from '../../../controllers/credito.service';
import { Credito } from '../../../models/credito.model';
// import { AdvancedSearchFilter } from '../../../shared/tabla/tabla.component';
import { LocalStorageService } from '../../../services/localStorage/local-storage.service';
// import { UtilsEstadoCuentaService } from '../../../main/estado-cuenta/services/utils-estado-cuenta.service';
import { UtilsService } from '../../../services/utils.service';
import { ActivatedRoute, Router } from '@angular/router';
// import { SuperService } from '../../../controllers/super.service';
import { SolicitudApoyo } from '../../../models/solicitud.apoyo';
import { SolicitudApoyoService } from '../../../controllers/solicitud.apoyo.service';
import { LoginCliente } from '../../auth/auth.service';
import { FormularioFlotanteComponent } from '../../../shared/formulario-flotante/formulario-flotante.component';
import { AutocompleteFieldComponent } from '../../../shared/generic-form/autocomplete-field/autocomplete-field.component';
import { SelectFieldComponent } from '../../../shared/generic-form/select-field/select-field.component';
import { SucursalService } from '../../../controllers/sucursal.service';
import { Option } from '../../../shared/generic-form/form-field/form-field.component';
import { SolicitudApoyoModalidad } from '../../../models/solicitud.apoyo.modalidad';

@Component({
  selector: 'app-apoyos-clientes',
  imports: [
    // CurrencyPipe,
    // NgClass,
    FormularioFlotanteComponent,
    AutocompleteFieldComponent,
    SelectFieldComponent,
  ],
  templateUrl: './apoyos-clientes.component.html',
  styleUrl: './apoyos-clientes.component.css',
})
export class ApoyosClientesComponent implements OnInit {
  creditos: Credito[] = [];
  estado: string = '';

  @Output() creditoSelected = new EventEmitter<Credito>();

  relations = [
    'estadoCuenta',
    'creditosPagos',
    'convenios.conveniosPagos',
    'abonos',
    'datosPersonaFisica.datosPersonales',
    'datosPersonaFisica.negocios',
    'datosPersonaFisica.datosPersonales.ciudades',
    'datosPersonasMorales.ciudades',
    'datosPersonasMorales.negocios',
    'datosPersonasMorales.representanteLegal',
    'productosFinancieros.plazos',
    'inversionesProgramas',
    'creditoComprobaciones',
  ];

  misApoyos: SolicitudApoyo[] = [];
  nuevoApoyo: Partial<SolicitudApoyo> = {};
  user?: LoginCliente;
  showSelProg = false;
  progSelect: any;
  sucursales: Option[] = [];
  disableBtnNvoApoyo: boolean = false;
  disableActionsBtns: boolean = true;

  extraData = {
    conditionals: JSON.stringify([
      ['created_at', '>=', new Date().getFullYear() + '-' + '01-01'],
      ['created_at', '<=', new Date().getFullYear() + '-' + '12-31'],
      ['deleted_at', 'IS NULL', null],
    ]),
  };

  constructor(
    private router: Router,
    private route: ActivatedRoute,
    public creditoController: CreditoService,
    public apoyosController: SolicitudApoyoService,
    private sucursalesController: SucursalService,
    private storage: LocalStorageService,
    public utils: UtilsService,
  ) {}

  ngOnInit() {
    this.user = this.storage.getClienteUser();
    console.log(this.user);

    this.getData();
    this.getSucursales();
  }

  async getData() {
    if (this.user) {
      const apoyos = await this.apoyosController.get(
        [
          {
            key: 'datos_personal_id',
            operator: '=',
            value: this.user.datos_personales_id,
          },
          { key: 'deleted_at', operator: 'IS NULL', value: null },
        ],
        undefined,
        [
          'datosPersonales',
          'programasApoyos',
          'solicitudesApoyosModalidades',
          'solicitudesApoyosModalidades.modalidadesMinistraciones',
          'solicitudesApoyosModalidades.modalidadesMinistraciones.modalidades',
        ],
      );

      this.misApoyos = apoyos.data || [];
      console.log('Mis Apoyos:', this.misApoyos);

      // -- verificar estado de la modatidad
      this.revisarEstadoModApoyo();
    }
  }

  async crearApoyo() {
    this.showSelProg = false;
    this.nuevoApoyo.datos_personal_id = this.user?.datos_personales_id;
    const apoyo = await this.apoyosController.new(this.nuevoApoyo);
    if (apoyo) {
      this.router.navigate(['/clientes/main/editar-apoyo', apoyo.id], {
        relativeTo: this.route,
      });
    }
  }

  public editar(id: number) {
    this.router.navigate(['/clientes/main/editar-apoyo', id], {
      relativeTo: this.route,
    });
  }

  async delete(id: number) {
    await this.apoyosController.switch(id, undefined, true);
    this.getData();
  }

  public selectProgramaNvoApoyo() {
    this.showSelProg = true;
  }

  async getSucursales() {
    const sucursales = await this.sucursalesController.all();
    this.sucursales = sucursales.map((sucursal) => {
      return {
        value: sucursal.id,
        label: sucursal.nombre,
      };
    });
    console.log('Sucursales:', this.sucursales);
  }

  getTotalApoyos(solicitud: SolicitudApoyo) {
    return this.utils.totalSolicitudApoyo(solicitud);
  }

  public isSomeActive() {
    return false; // this.creditos.some(credito => credito.estado === 'ACTIVO' && !credito.deleted_at)
  }

  getEstadoModalidadApoyo(modalidades: SolicitudApoyoModalidad[]) {
    const length = modalidades.length - 1;
    return length >= 0 ? modalidades[length].estado : 'NA'; // -- INFO: último estado
  }

  /**
   * Revisar el estado de los Apoyos para
   * deshabilitar o desactivar el botón de
   * "Crear nuevo apoyo" y los botones de
   * acciones
   **/
  private revisarEstadoModApoyo() {
    if (this.misApoyos.length == 0) {
      return;
    }

    for (let apoyo of this.misApoyos) {
      const estado = this.getEstadoModalidadApoyo(
        apoyo.solicitudes_apoyos_modalidades || [],
      );
      switch (estado) {
        case 'CAPTURANDO':
          this.disableActionsBtns = false;
          break;

        case 'CONCLUIDO':
          this.disableBtnNvoApoyo = false;
          break;

        case 'RECHAZADO':
          this.disableBtnNvoApoyo = false;
          break;

        default:
          this.disableBtnNvoApoyo = true;
          this.disableActionsBtns = true;
      }
    }
  }
}
