import { Component, Input, OnChanges, SimpleChanges } from '@angular/core';
import { Credito } from '../../../../models/credito.model';
import { CurrencyPipe, DatePipe } from '@angular/common';
import { CreditoAbono } from '../../../../models/credito.abono';

@Component({
    selector: 'app-abonos-realizados',
    imports: [CurrencyPipe, DatePipe],
    templateUrl: './ultimos-abonos.component.html',
    styleUrl: './ultimos-abonos.component.css'
})
export class UltimosAbonosComponent implements OnChanges {
  @Input() credito?: Credito;

  abonos: CreditoAbono[] = [];

  ultimaFechaAbono?: string;

  ngOnChanges(changes: SimpleChanges): void {
    if (
      changes['credito'] &&
      this.credito &&
      Array.isArray(this.credito.estado_cuenta?.abonos_distribuidos)
    ) {
      const rawAbonos = this.credito.estado_cuenta.abonos_distribuidos;

      this.abonos = rawAbonos
        .map(item => item.abono)
        .filter((abono): abono is CreditoAbono => !!abono)
        .sort((a, b) => new Date(b.fecha).getTime() - new Date(a.fecha).getTime());

      this.ultimaFechaAbono = this.abonos.length > 0 ? this.abonos[0].fecha : undefined;
    }
  }

}
