import { Component, Input, OnChanges, SimpleChanges } from '@angular/core';
import { Credito } from '../../../../models/credito.model';
import { CurrencyPipe, DatePipe } from '@angular/common';

@Component({
    selector: 'app-proximo-pago',
    imports: [CurrencyPipe, DatePipe],
    templateUrl: './proximo-pago.component.html',
    styleUrl: './proximo-pago.component.css'
})
export class ProximoPagoComponent implements OnChanges{
  @Input() credito?: Credito;

  ultimoPeriodo?: {
    pago_programado_total: number;
    saldo_insoluto: number;
    saldo_total: number;
    saldo_vencido: number;
    status: string;
    fecha: string;
  };


  ngOnChanges(changes: SimpleChanges): void {
    if (changes['credito'] && this.credito?.estado_cuenta?.periodo_vigente) {
      const periodo = this.credito.estado_cuenta.periodo_vigente;

      this.ultimoPeriodo = {
        pago_programado_total: periodo.pago_programado_total,
        saldo_insoluto: periodo.saldo_insoluto,
        saldo_total: periodo.saldo_total,
        saldo_vencido: periodo.saldo_vencido,
        status: periodo.status,
        fecha: periodo.fecha
      };
    }
  }

}
